#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void softmax_kernel(const __half* input, __half* output, int batch_size, int num_features) {
    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const __half* input_batch = input + batch_idx * num_features;
    __half* output_batch = output + batch_idx * num_features;

    // Shared memory for reduction operations
    extern __shared__ __half shared_data[];

    // Step 1: Find maximum value in the batch
    __half max_val = input_batch[0];
    for (int i = 1; i < num_features; i++) {
        max_val = __hmax(max_val, input_batch[i]);
    }

    // Store max value in shared memory
    shared_data[0] = max_val;
    __syncthreads();

    // Step 2: Compute exp(x - max) for each element
    for (int i = threadIdx.x; i < num_features; i += blockDim.x) {
        __half val = __hsub(input_batch[i], shared_data[0]);
        shared_data[i] = __hexp(val);
    }
    __syncthreads();

    // Step 3: Sum all exponentials
    __half sum_exp = __float2half(0.0f);
    for (int i = 0; i < num_features; i++) {
        sum_exp = __hadd(sum_exp, shared_data[i]);
    }

    // Step 4: Normalize (divide by sum)
    for (int i = threadIdx.x; i < num_features; i += blockDim.x) {
        output_batch[i] = __hdiv(shared_data[i], sum_exp);
    }
}

